//! Spelunky Classic 1.1 game logic, running on the `gm` runtime (`docs/design/runtime.md`, section 11).
//!
//! The logic is the original GML, transpiled (`generated/`, generated by `crates/transpile`; regenerate with
//! `scripts/transpile`, never edit by hand). Hand-written code is limited to:
//!
//! - [`builtins`]: the GM8 built-in functions as generated code calls them, with shims for the ones the
//!   runtime doesn't provide yet (each fails loudly, naming its ticket).
//! - [`overrides`]: the script override table (`SS_*`).
//! - [`Game`]: the API the frontend, the replay harness and agents use. Nothing GML-specific leaks
//!   through it.
//!
//! Headless and deterministic, like `gm`: no mutable globals (the program table and string literals are
//! immutable caches built on first use), no clock, no I/O.

pub mod builtins;
#[rustfmt::skip]
mod generated;
pub mod overrides;
mod rt;

use std::sync::{Arc, LazyLock};

use gm::{Error, GmlError, InputEvent, Program, World};

/// The program table: built from the generated definitions the first time it's needed, then shared by
/// every world (worlds hold a `&'static Program`).
static PROGRAM: LazyLock<Program> = LazyLock::new(generated::build_program);

/// The game's program: objects, resolved event handlers, variable names.
pub fn program() -> &'static Program {
    &PROGRAM
}

/// A GML error as `unit:line: message`, with variable names instead of the ids `gm::Error` holds.
pub fn describe(e: &GmlError) -> String {
    let p = program();
    let what = match &e.error {
        Error::UnsetVar(v) => format!("unknown variable {}", p.var_name(*v)),
        Error::UnsetGlobal(v) => format!("unknown variable global.{}", p.global_name(*v)),
        Error::ReadOnly(v) => format!("cannot assign to read-only variable {}", p.var_name(*v)),
        other => other.to_string(),
    };
    format!("{}:{}: {what}", e.unit, e.line)
}

/// What a run depends on besides the assets and the input.
#[derive(Clone, Debug, Default)]
pub struct Config {
    /// The RNG state when the first room starts (the oracle records it with each replay).
    pub seed: i32,
    /// The connected joystick (the replay's `joystick` directive). `None`, the oracle's only setting, makes
    /// every `joystick_*` function answer as OpenGMK's stubs do.
    pub joystick: Option<trace::replay::JoystickInfo>,
}

/// A running game: one `gm::World`. Cloning it is a savestate.
#[derive(Clone)]
pub struct Game {
    world: World,
}

impl Game {
    /// A game before its first room: no instances yet. See [`start`](Self::start).
    pub fn new(assets: Arc<gm::Assets>, config: Config) -> Game {
        let mut world = World::new(
            program(),
            assets,
            config.seed,
            generated::LAST_INSTANCE_ID,
            generated::FONT_SLOTS,
        );
        world.connect_joystick(config.joystick.as_ref());
        Game { world }
    }

    /// Starts the game in the first room of the room order (`rScreenInit`): loads it with its game start
    /// events and draws frame 0. From then on [`step`](Self::step) performs room changes itself.
    pub fn start(&mut self) -> Result<(), GmlError> {
        self.world.start_game()
    }

    /// Whether the game has ended (`game_end`); steps then do nothing.
    pub fn ended(&self) -> bool {
        self.world.ended()
    }

    /// Runs one frame with this frame's input events.
    pub fn step<'a>(
        &mut self,
        input: impl IntoIterator<Item = &'a InputEvent>,
    ) -> Result<(), GmlError> {
        self.world.step(input)
    }

    /// [`step`](Self::step), recording what the frame draws into `frame` for the renderer.
    pub fn step_drawing<'a>(
        &mut self,
        input: impl IntoIterator<Item = &'a InputEvent>,
        frame: &mut draw::Frame,
    ) -> Result<(), GmlError> {
        self.world.step_drawing(input, frame)
    }

    /// The state after the last frame, in the oracle's trace schema.
    pub fn trace(&self) -> trace::Frame {
        self.world.trace_frame()
    }

    /// The world, for inspection.
    pub fn world(&self) -> &World {
        &self.world
    }
}
